    /// A live mob with a non-finite position must fail the save closed: the
    /// codec rejects it before the atomic write, the file is never created,
    /// and the world keeps its unsaved-changes flag for a later retry.
    #[test]
    fn mob_persistence_rejects_a_non_finite_live_mob_without_writing() {
        let dir = tempfile::tempdir().expect("tempdir");
        let save_path = dir.path().join("bad-mobs.mcvx");
        let mut session = WorldSession::new_session_with_mode(
            24681,
            save_path.clone(),
            DEFAULT_SEASON_LENGTH_DAYS,
            GameMode::Survival,
        );
        let cpos = ChunkPos { x: 0, y: 1, z: 0 };
        session
            .world
            .insert_chunk_for_test(cpos, generate_chunk_seeded(cpos, 24681, Season::Summer));
        session.world.set_block_immediate(0, 40, 5, BlockId::Brick);
        assert!(session.world.has_unsaved_changes());

        session
            .mobs_mut()
            .push(Mob::new(MobKind::Pig, Vec3::new(f32::NAN, 64.0, 0.0), 0.0));
        let result = save_current_world(&mut session);

        assert!(
            matches!(result, Err(PersistenceError::InvalidMobState)),
            "a non-finite mob position is a codec rejection, got {result:?}"
        );
        assert!(!save_path.exists(), "no bytes are written on rejection");
        assert!(
            session.world.has_unsaved_changes(),
            "the failed save keeps the retry flag set"
        );
    }

    #[test]
    fn survival_mode_vitals_and_chests_survive_save_and_restart() {
        use opencraft::player::container::Container;
        use opencraft::player::inventory::{ChestSlots, Item, ItemId, Material, CHEST_SLOTS};

        let dir = tempfile::tempdir().expect("tempdir");
        let save_path = dir.path().join("survival.mcvx");
        let mut session = WorldSession::new_session_with_mode(
            5150,
            save_path.clone(),
            DEFAULT_SEASON_LENGTH_DAYS,
            GameMode::Survival,
        );
        let vitals = SurvivalState::new(4, 11, 120).expect("in-range vitals");
        session.player.survival = vitals;
        let mut chest: ChestSlots = [None; CHEST_SLOTS];
        chest[0] = Some(Item::new(ItemId::Material(Material::Apple), 3).expect("apple"));
        chest[26] = Some(Item::new(ItemId::Material(Material::Bread), 1).expect("bread"));
        let chest = Container::from_slots(chest);
        session.chests.insert(IVec3::new(2, 30, -5), chest.clone());

        // A stale fly byte must not leak through the save writer: the persisted
        // mode canonicalises it to false even though the field itself is true.
        session.player.fly_mode = true;
        assert!(
            !session.player.can_fly(),
            "Survival cannot fly even with a hand-set fly flag"
        );

        save_current_world(&mut session).expect("save succeeds");
        let loaded = load_world_from_path(&save_path).expect("load succeeds");
        assert_eq!(loaded.mode, GameMode::Survival);
        assert_eq!(loaded.player.survival, vitals);
        assert!(
            !loaded.player.fly_mode,
            "the writer canonicalises Survival fly=false"
        );
        assert_eq!(loaded.chests.len(), 1);
        assert_eq!(loaded.chests[&IVec3::new(2, 30, -5)], chest);
        assert_eq!(
            loaded.chests[&IVec3::new(2, 30, -5)].slot(0),
            Some(Item::new(ItemId::Material(Material::Apple), 3).expect("apple"))
        );
        assert_eq!(
            loaded.chests[&IVec3::new(2, 30, -5)].slot(26),
            Some(Item::new(ItemId::Material(Material::Bread), 1).expect("bread"))
        );

        let restored = WorldSession::session_from_save(loaded, save_path.clone());
        assert_eq!(restored.save_mode, GameMode::Survival);
        assert_eq!(restored.player.mode(), GameMode::Survival);
        assert_eq!(restored.player.survival, vitals);
        assert_eq!(restored.chests[&IVec3::new(2, 30, -5)], chest);
        assert!(!restored.player.fly_mode);
        assert!(!restored.player.can_fly());
    }

    #[test]
    fn inventory_tools_cursor_main_slots_and_grids_survive_named_world_restart() {
        use opencraft::player::inventory::{
            Item, ItemId, Material, ToolKind, ToolTier, INVENTORY_SLOTS,
        };
        use opencraft::player::physics::Player;

        let dir = tempfile::tempdir().expect("tempdir");
        let save_path = dir.path().join("full.mcvx");
        let mut session =
            WorldSession::new_session(909, save_path.clone(), DEFAULT_SEASON_LENGTH_DAYS);

        let mut slots = [None; INVENTORY_SLOTS];
        slots[0] = Some(Item::new(ItemId::Block(BlockId::Stone), 5).expect("stone"));
        slots[HOTBAR_SLOTS + 4] =
            Some(Item::new(ItemId::Material(Material::Stick), 3).expect("sticks"));
        let axe =
            Item::tool_with_durability(ToolKind::Pickaxe, ToolTier::Stone, 77).expect("worn axe");
        let inventory = Inventory::from_parts(slots, Some(axe));

        let mut player_grid = CraftingGrid::new(GridKind::Player);
        player_grid
            .set(
                1,
                Some(Item::new(ItemId::Material(Material::Stick), 1).expect("stick")),
            )
            .expect("player grid cell");
        let mut table_grid = CraftingGrid::new(GridKind::Table);
        table_grid
            .set(
                7,
                Some(Item::new(ItemId::Block(BlockId::IronOre), 2).expect("ore")),
            )
            .expect("table grid cell");

        let mut player = Player::with_inventory(
            session.player.position,
            inventory.clone(),
            player_grid.clone(),
            table_grid.clone(),
        );
        player.yaw = 1.5;
        assert!(player.select_slot(1));
        session.player = player;

        save_current_world(&mut session).expect("save succeeds");
        let loaded = load_world_from_path(&save_path).expect("load succeeds");
        assert_eq!(loaded.player.selected_slot, 1);
        assert_eq!(loaded.player.inventory, inventory);
        assert_eq!(loaded.player.player_grid, player_grid);
        assert_eq!(loaded.player.table_grid, table_grid);

        let mut restored = WorldSession::session_from_save(loaded, save_path.clone());
        assert_eq!(restored.player.selected_slot(), 1);
        assert_eq!(restored.player.inventory(), &inventory);
        assert_eq!(restored.player.player_grid(), &player_grid);
        assert_eq!(restored.player.table_grid(), &table_grid);
        assert_eq!(
            restored
                .player
                .inventory()
                .cursor()
                .and_then(|item| item.durability()),
            Some(77),
            "worn tool durability survives the runtime/save boundary"
        );

        // Saving the restored session reproduces byte-identical state.
        let second_path = dir.path().join("full-again.mcvx");
        restored.save_path = second_path.clone();
        save_current_world(&mut restored).expect("re-save succeeds");
        assert_eq!(
            std::fs::read(&save_path).expect("read first save"),
            std::fs::read(&second_path).expect("read second save"),
            "session restore followed by save is byte-identical"
        );
    }

