    #[test]
    fn mob_audio_slots_maps_every_event_to_its_slot() {
        let cases = [
            (
                MobAudioFrame {
                    idle: true,
                    ..MobAudioFrame::default()
                },
                [Some(SoundSlot::MobIdle), None, None, None, None],
            ),
            (
                MobAudioFrame {
                    hurt: true,
                    ..MobAudioFrame::default()
                },
                [None, Some(SoundSlot::MobHurt), None, None, None],
            ),
            (
                MobAudioFrame {
                    death: true,
                    ..MobAudioFrame::default()
                },
                [None, None, Some(SoundSlot::MobDeath), None, None],
            ),
            (
                MobAudioFrame {
                    bow_release: true,
                    ..MobAudioFrame::default()
                },
                [None, None, None, Some(SoundSlot::BowRelease), None],
            ),
            (
                MobAudioFrame {
                    arrow_impact: true,
                    ..MobAudioFrame::default()
                },
                [None, None, None, None, Some(SoundSlot::ArrowImpact)],
            ),
        ];
        for (frame, expected) in cases {
            assert_eq!(mob_audio_slots(frame), expected);
        }
        assert_eq!(
            mob_audio_slots(MobAudioFrame {
                idle: true,
                hurt: true,
                death: true,
                bow_release: true,
                arrow_impact: true,
            }),
            [
                Some(SoundSlot::MobIdle),
                Some(SoundSlot::MobHurt),
                Some(SoundSlot::MobDeath),
                Some(SoundSlot::BowRelease),
                Some(SoundSlot::ArrowImpact),
            ]
        );
        assert_eq!(mob_audio_slots(MobAudioFrame::default()), [None; 5]);
    }

    #[test]
    fn bow_release_reports_fired_only_on_an_accepted_shot() {
        let dir = tempfile::tempdir().expect("tempdir");
        let mut session = bow_session(dir.path(), 103, "bow-fired-flag.mcvx", GameMode::Survival);
        let mut bow = BowState::new();

        // A sub-threshold tap is a cancel: the draw resets, nothing fires.
        let target = bow_charge_candidate(&session, true, true, true).expect("bow target");
        bow.tick(0.1, Some(target));
        let tap = release_bow(&mut bow, &mut session, true, true);
        assert!(!tap.fired, "a tap is not a fired shot");
        assert_eq!(tap.error, None, "a tap is a silent cancel");
        assert!(session.arrows().is_empty());

        // An accepted full draw fires with no refusal attached.
        bow_draw_to_full(&mut bow, &session);
        let accepted = release_bow(&mut bow, &mut session, true, true);
        assert!(accepted.fired, "a full draw fires");
        assert_eq!(accepted.error, None);
        assert_eq!(session.arrows().len(), 1);
    }

    #[test]
    fn bow_without_ammo_refuses_without_wear_and_reports_the_exact_notice() {
        let dir = tempfile::tempdir().expect("tempdir");
        let mut session = bow_session(dir.path(), 102, "bow-no-ammo.mcvx", GameMode::Survival);
        for _ in 0..3 {
            assert!(session
                .player
                .consume_item(ItemId::Material(Material::Arrow))
                .is_some());
        }
        assert_eq!(arrow_count(&session), 0);
        let durability_before = selected_bow_durability(&session);

        let mut bow = BowState::new();
        bow_draw_to_full(&mut bow, &session);
        let release = release_bow(&mut bow, &mut session, true, true);

        assert!(!release.fired, "a refused shot never fires");
        assert_eq!(release.error, Some(BowFireError::NoAmmo));
        assert_eq!(bow_release_notice(release.error), Some("No arrows"));
        assert!(session.arrows().is_empty(), "a refused shot spawns nothing");
        assert_eq!(
            selected_bow_durability(&session),
            durability_before,
            "a refused shot wears nothing"
        );
        assert_eq!(bow.progress(), None);
    }

    #[test]
    fn bow_state_cleared_by_enter_screen_enter_playing_death_and_session_swap() {
        let cli = CliConfig::parse_args(Vec::<String>::new());
        let mut app = GameApp::new(
            cli,
            WorldSession::new_session(
                1,
                PathBuf::from("/nonexistent/initial.mcvx"),
                DEFAULT_SEASON_LENGTH_DAYS,
            ),
        );
        let target = BowTarget::new(0, bow_item()).expect("bow target");

        // Every lifecycle screen entry clears a live charge.
        app.bow.tick(0.5, Some(target));
        assert!(app.bow.progress().is_some());
        app.enter_screen(LifecycleScreen::MainMenu);
        assert_eq!(app.bow.progress(), None, "screen entry clears the draw");

        // Entering Playing clears a draw too (defensive trip-through-menu).
        app.bow.tick(0.5, Some(target));
        assert!(app.bow.progress().is_some());
        app.enter_playing();
        assert_eq!(app.bow.progress(), None, "Playing entry clears the draw");

        // A Death entry routes through enter_screen.
        app.bow.tick(0.5, Some(target));
        assert!(app.bow.progress().is_some());
        app.enter_screen(LifecycleScreen::Death);
        assert_eq!(app.bow.progress(), None, "Death entry clears the draw");

        // A world swap (on_session_installed) clears the draw.
        app.bow.tick(0.5, Some(target));
        assert!(app.bow.progress().is_some());
        app.start_world_session(WorldSession::new_session(
            42,
            PathBuf::from("/nonexistent/replacement.mcvx"),
            DEFAULT_SEASON_LENGTH_DAYS,
        ));
        assert_eq!(app.bow.progress(), None, "session swap clears the draw");
    }

    #[test]
    fn reset_panel_holds_clears_a_live_draw_and_meal() {
        let mut mining = MiningState::new();
        let mut eating = EatingState::new();
        let mut bow = BowState::new();
        let meal = EatingTarget::new(0, apple_item(1), 10).expect("apple target");
        eating.tick(0.5, Some(meal));
        let target = BowTarget::new(0, bow_item()).expect("bow target");
        bow.tick(0.5, Some(target));
        assert!(eating.progress().is_some());
        assert!(bow.progress().is_some());

        reset_panel_holds(&mut mining, &mut eating, &mut bow);

        assert_eq!(eating.progress(), None, "meal cleared");
        assert_eq!(bow.progress(), None, "draw cleared");
        assert!(mining.progress().is_none());
    }

    #[test]
    fn bow_frame_progress_bar_prefers_eating_then_bow_then_mining() {
        use opencraft::ui::hud::{BOW_FILL_COLOR, EATING_FILL_COLOR};

        let eating = frame_progress_bar(Some(0.5), Some(0.5), Some(0.5), 1280, 720)
            .expect("eating wins when every bar exists");
        assert_eq!(eating[1].color, EATING_FILL_COLOR);

        let bow =
            frame_progress_bar(None, Some(0.5), Some(0.5), 1280, 720).expect("bow beats mining");
        assert_eq!(bow[1].color, BOW_FILL_COLOR);

        let mining = frame_progress_bar(None, None, Some(0.5), 1280, 720)
            .expect("mining is the fallback bar");
        assert_eq!(
            mining[1].color,
            mining_progress_quads(0.5, 1280, 720)[1].color
        );
        assert_ne!(eating[1].color, bow[1].color);
        assert_ne!(bow[1].color, mining[1].color);

        assert!(frame_progress_bar(None, None, None, 1280, 720).is_none());
    }

    /// A two-entry pack registry (one block, one item) with real, non-placeholder
    /// definitions, built from an inline spec rather than the crate's `packs/`.
    fn main_ruby_registry() -> Arc<ContentRegistry> {
        use opencraft::content::spec::{BlockEntry, BlockTextures, ItemEntry, PackAsset};

        let mut spec = PackContentSpec::default();
        spec.blocks.push(BlockEntry {
            id: "mymod:ruby_ore".to_string(),
            display_name: None,
            textures: BlockTextures {
                all: Some("ruby_ore.png".to_string()),
                ..BlockTextures::default()
            },
            hardness: 1.0,
            drop: Some("mymod:ruby".to_string()),
            tool: None,
            stack_limit: 64,
        });
        spec.items.push(ItemEntry {
            id: "mymod:ruby".to_string(),
            display_name: None,
            icon: "ruby.png".to_string(),
            stack_limit: 64,
            food: None,
        });
        for path in ["ruby_ore.png", "ruby.png"] {
            spec.assets.insert(
                path.to_string(),
                PackAsset {
                    rgba: vec![0x33; 1024],
                    source_side: 16,
                },
            );
        }

        let packs = vec![(
            PackIdentity {
                folder: "mymod-ruby".to_string(),
                version: Some("1.0".to_string()),
            },
            spec,
        )];
        let (registry, report) = build_registry(ContentRegistry::builtin(), &packs);
        assert_eq!(report.errors(), 0, "fixture registry is clean: {report:?}");
        Arc::new(registry)
    }

    /// Pack registry with an authored ruby tier (speed 9, durability 900,
    /// damage 9), a ruby pickaxe and sword, ruby ore that drops a ruby item,
    /// and an altar block whose authored drop is the pack pickaxe itself.
    fn pack_tool_registry() -> Arc<ContentRegistry> {
        use opencraft::content::spec::{
            BlockEntry, BlockTextures, ItemEntry, PackAsset, TierEntry, ToolEntry,
        };

        let mut spec = PackContentSpec::default();
        spec.blocks.push(BlockEntry {
            id: "mymod:ruby_ore".to_string(),
            display_name: None,
            textures: BlockTextures {
                all: Some("ore.png".to_string()),
                ..BlockTextures::default()
            },
            hardness: 3.0,
            drop: Some("mymod:ruby".to_string()),
            tool: Some(ToolKind::Pickaxe),
            stack_limit: 64,
        });
        spec.blocks.push(BlockEntry {
            id: "mymod:tool_altar".to_string(),
            display_name: None,
            textures: BlockTextures {
                all: Some("altar.png".to_string()),
                ..BlockTextures::default()
            },
            hardness: 1.0,
            drop: Some("mymod:ruby_pickaxe".to_string()),
            tool: None,
            stack_limit: 64,
        });
        spec.items.push(ItemEntry {
            id: "mymod:ruby".to_string(),
            display_name: None,
            icon: "ruby.png".to_string(),
            stack_limit: 64,
            food: None,
        });
        spec.tiers.push(TierEntry {
            id: "mymod:ruby".to_string(),
            display_name: Some("Ruby".to_string()),
            speed: 9.0,
            durability: 900,
            damage: 9,
        });
        spec.tools.push(ToolEntry {
            id: "mymod:ruby_pickaxe".to_string(),
            display_name: Some("Ruby Pickaxe".to_string()),
            kind: ToolKind::Pickaxe,
            tier: "mymod:ruby".to_string(),
            icon: "pickaxe.png".to_string(),
        });
        spec.tools.push(ToolEntry {
            id: "mymod:ruby_sword".to_string(),
            display_name: Some("Ruby Sword".to_string()),
            kind: ToolKind::Sword,
            tier: "mymod:ruby".to_string(),
            icon: "sword.png".to_string(),
        });
        for path in [
            "ore.png",
            "altar.png",
            "ruby.png",
            "pickaxe.png",
            "sword.png",
        ] {
            spec.assets.insert(
                path.to_string(),
                PackAsset {
                    rgba: vec![0x44; 1024],
                    source_side: 16,
                },
            );
        }

        let (registry, report) = build_registry(
            ContentRegistry::builtin(),
            &[(
                PackIdentity {
                    folder: "mymod-tools".to_string(),
                    version: Some("1.0".to_string()),
                },
                spec,
            )],
        );
        assert_eq!(report.errors(), 0, "fixture registry is clean: {report:?}");
        Arc::new(registry)
    }

    fn modded_sample_save(seed: u32) -> WorldSaveData {
        let mut data = sample_save(seed);
        let mut chunk = FxHashMap::default();
        chunk.insert(
            10,
            BlockId::Modded(opencraft::world::block::BUILTIN_BLOCK_COUNT),
        );
        data.chunk_edits.insert(ChunkPos::new(1, 2, 3), chunk);
        let mut inventory = Inventory::empty();
        inventory
            .insert(Item::new(ItemId::Item(0), 5).expect("ruby stack"))
            .expect("the empty inventory accepts the stack");
        data.player.inventory = inventory;
        data
    }

    #[test]
    fn save_current_world_names_modded_content_through_the_session_registry() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("modded-session.mcvx");
        let registry = main_ruby_registry();
        let mut session = WorldSession::new_session_with_mode_and_registry(
            4242,
            path.clone(),
            DEFAULT_SEASON_LENGTH_DAYS,
            GameMode::Creative,
            Arc::clone(&registry),
        );
        let ruby_ore = BlockId::Modded(opencraft::world::block::BUILTIN_BLOCK_COUNT);
        insert_test_chunk_with_face_neighbors(&mut session, BlockId::Stone);
        session.world.set_block_immediate(0, 10, 0, ruby_ore);
        session
            .player
            .collect_item(Item::new(ItemId::Item(0), 5).expect("ruby stack"));

        save_current_world(&mut session).expect("the session save writes");

        let loaded =
            opencraft::world::persistence::load_world_from_path_with(&path, registry.as_ref())
                .expect("the save loads with the pack registry");
        assert_eq!(
            loaded.unresolved, 0,
            "no placeholders against the same pack"
        );
        let block = loaded.registry.block(ruby_ore).expect("ruby ore resolves");
        assert_eq!(block.name, "mymod:ruby_ore");
        assert!(
            !block.placeholder,
            "the real definition was written by name"
        );
        let item = loaded.registry.item(0).expect("ruby resolves");
        assert_eq!(item.name, "mymod:ruby");
        assert!(!item.placeholder);
        assert_eq!(
            loaded.data.player.inventory.slots()[0].map(|item| item.id()),
            Some(ItemId::Item(0))
        );
        assert_eq!(
            loaded
                .data
                .chunk_edits
                .get(&ChunkPos::new(0, 0, 0))
                .and_then(|chunk| chunk.get(&(linear_index(0, 10, 0) as u16)))
                .copied(),
            Some(ruby_ore)
        );
    }

    #[test]
    fn startup_session_with_loads_v8_content_through_the_pack_registry() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("modded-startup.mcvx");
        let path_str = path.to_str().expect("utf8 path");
        let registry = main_ruby_registry();
        save_world_to_path_with(&path, &modded_sample_save(33), registry.as_ref())
            .expect("write modded save");
        let ruby_ore = BlockId::Modded(opencraft::world::block::BUILTIN_BLOCK_COUNT);

        let cli = CliConfig::parse_args(["--save", path_str]);
        let mut loaded = startup_session_with(&cli, &registry, &ConfigRuntime::defaults());
        assert_eq!(
            loaded
                .registry
                .block(ruby_ore)
                .map(|block| block.name.as_str()),
            Some("mymod:ruby_ore")
        );
        assert!(!loaded.registry.block(ruby_ore).unwrap().placeholder);
        assert_eq!(loaded.registry.item_def_name(0), Some("mymod:ruby"));
        assert_eq!(loaded.take_content_notice(), None, "same stack is silent");
        assert_eq!(
            loaded.player.inventory().slots()[0].map(|item| item.id()),
            Some(ItemId::Item(0)),
            "the saved item id survives the registry-aware load"
        );

        // The same save under the built-in registry still opens, with the saved
        // names as placeholders and a readable non-blocking notice.
        let mut builtin = startup_session_with(
            &cli,
            &ContentRegistry::builtin_arc(),
            &ConfigRuntime::defaults(),
        );
        assert_eq!(
            builtin
                .registry
                .block(ruby_ore)
                .map(|block| block.name.as_str()),
            Some("mymod:ruby_ore"),
            "the placeholder keeps the saved name"
        );
        assert!(builtin.registry.block(ruby_ore).unwrap().placeholder);
        let notice = builtin
            .take_content_notice()
            .expect("a changed stack yields a readable notice");
        assert!(notice.contains("missing pack `mymod-ruby`"), "{notice}");
        assert!(
            notice.contains("2 saved content names are unavailable and render as placeholders"),
            "{notice}"
        );

        // A fresh branch freezes exactly the supplied registry.
        let fresh = startup_session_with(
            &CliConfig::parse_args(["--new", "--seed", "9", "--save", path_str]),
            &registry,
            &ConfigRuntime::defaults(),
        );
        assert!(Arc::ptr_eq(&fresh.registry, &registry));
    }

    // -----------------------------------------------------------------------
    // M014/S01-T07: startup config loading and app/session rules wiring
    // -----------------------------------------------------------------------

    /// Build a settings/packs/config temp tree with a custom player config.
    fn startup_content_with_player_toml(dir: &Path, player_toml: &str) -> StartupContent {
        let config_dir = dir.join(opencraft::config::CONFIG_DIR);
        std::fs::create_dir_all(&config_dir).expect("create config dir");
        std::fs::write(config_dir.join("player.toml"), player_toml).expect("write player.toml");
        StartupContent::load(
            &dir.join("settings.toml"),
            dir.join("packs"),
            Some(&config_dir),
        )
    }

    fn config_warnings(content: &StartupContent) -> Vec<&SettingsWarning> {
        content
            .startup_warnings
            .iter()
            .filter(|warning| warning.field.starts_with("config/"))
            .collect()
    }

    fn one_second_walk_displacement(session: &mut WorldSession) -> f32 {
        session.player.fly_mode = false;
        session.player.yaw = 0.0;
        let input = InputState {
            forward: true,
            ..Default::default()
        };
        let start = session.player.position;
        for _ in 0..60 {
            session
                .player
                .update(1.0 / 60.0, &input, |_, _, _| BlockId::Air);
        }
        Vec3::new(
            session.player.position.x - start.x,
            0.0,
            session.player.position.z - start.z,
        )
        .length()
    }

    #[test]
    fn startup_config_loads_from_injected_dir() {
        let dir = tempfile::tempdir().expect("tempdir");
        let content = startup_content_with_player_toml(
            dir.path(),
            "[movement]\nwalk_speed = 6.0\n\n[camera]\nz_far = 800.0\n",
        );

        assert_eq!(content.config.f32("movement.walk_speed"), 6.0);
        assert_eq!(content.config.f32("camera.z_far"), 800.0);
        assert!(
            config_warnings(&content).is_empty(),
            "a valid injected config must not surface a config warning: {:?}",
            content.startup_warnings
        );
    }

    #[test]
    fn startup_config_rules_reach_startup_session() {
        let dir = tempfile::tempdir().expect("tempdir");
        let content = startup_content_with_player_toml(
            dir.path(),
            "[movement]\nwalk_speed = 6.0\n\n[camera]\nz_far = 800.0\n",
        );
        let save_path = dir.path().join("fresh.mcvx");
        let cli =
            CliConfig::parse_args(["--new", "--save", save_path.to_str().expect("utf8 path")]);

        let mut session = startup_session_with(&cli, &content.base_registry, &content.config);
        assert_eq!(session.player.movement.walk_speed, 6.0);
        assert_eq!(session.camera.z_far, 800.0);
        let fast = one_second_walk_displacement(&mut session);
        assert!(
            (fast - 6.0).abs() < 0.2,
            "walk_speed = 6.0 must move 6 blocks in 1 s, got {fast}"
        );

        // The same launch with default rules keeps today's 4.6 blocks/s.
        let mut default_session =
            startup_session_with(&cli, &content.base_registry, &ConfigRuntime::defaults());
        let normal = one_second_walk_displacement(&mut default_session);
        assert!(
            (normal - 4.6).abs() < 0.2,
            "default walk speed must move 4.6 blocks in 1 s, got {normal}"
        );
    }

